import { withVersion } from "@/lib/image-version";
import { HeroSlideshow } from "@/components/home/HeroSlideshow";

// Resolved server-side (withVersion reads file mtimes via node:fs, which can't reach the
// browser bundle) and handed to the client slideshow as plain src/alt pairs.
// 3840x2160 international photos generated by scripts/import-hero-photos.mjs.
const slides = [
  { src: withVersion("/images/hero/1.jpg"), alt: "Tomorrowland festival main stage, Belgium" },
  { src: withVersion("/images/hero/2.jpg"), alt: "Arc de Triomphe, Paris" },
  { src: withVersion("/images/hero/3.jpg"), alt: "Welcome to Fabulous Las Vegas sign, USA" },
  { src: withVersion("/images/hero/4.jpg"), alt: "DJs performing to the Tomorrowland crowd" },
  { src: withVersion("/images/hero/5.jpg"), alt: "Marina Bay Sands, Singapore" },
  { src: withVersion("/images/hero/6.jpg"), alt: "Statue of Liberty, New York" },
  { src: withVersion("/images/hero/7.jpg"), alt: "Phang Nga Bay viewpoint, Thailand" },
  { src: withVersion("/images/hero/8.jpg"), alt: "Table Mountain over Cape Town, South Africa" },
];

export function Hero() {
  return <HeroSlideshow slides={slides} />;
}
